Function r <- Factorial(n As Integer)
  Define r As Integer;
  If n = 0 Then
    r <- 1;
  Else
    r <- n * Factorial(n - 1);
  EndIf
EndFunction

Algorithm Principal
  Write Factorial(5);
EndAlgorithm

Subroutine Hanoi(n As Integer, origen As String, destino As String, auxiliar As String)
  If n > 0 Then
    Hanoi(n - 1, origen, auxiliar, destino);
    Write "Mover disco ", n, " de ", origen, " a ", destino;
    Hanoi(n - 1, auxiliar, destino, origen);
  EndIf
EndSubroutine

Algorithm Torre
  Hanoi(3, "A", "C", "B");
EndAlgorithm
